package engine

import (
	"fmt"
	"os"
	"strings"
	"testing"
	"time"
)

// The tables in docs/development/mock-worker.md are this engine's own output, regenerated by
//
//	UPDATE_SIM_DOCS=1 go test ./internal/sim/engine -run TestDocsCurves
//
// and checked against the committed text on every run, so the documentation cannot drift from the model.
const (
	docsPath   = "../../../docs/development/mock-worker.md"
	beginMark  = "<!-- sim-curves:begin -->"
	endMark    = "<!-- sim-curves:end -->"
	curveSteps = 60
)

func noiseFree(name string) Params {
	p, _ := Profile(name)
	p.StepNoiseCV, p.PrefillNoiseCV, p.OutputCV = 0, 0, 0
	return p
}

func mustEngine(p Params, seqs, queue int) *Engine {
	e, err := New(Config{Params: p, Seed: 1, MaxSeqs: seqs, MaxQueue: queue, OutputMeanTokens: 100000})
	if err != nil {
		panic(err)
	}
	return e
}

func fmtMs(d time.Duration) string { return fmt.Sprintf("%.1f", float64(d)/float64(time.Millisecond)) }

func prefillCurve(p Params, n int) time.Duration {
	e := mustEngine(p, 4, 0)
	info, evs, err := e.Submit(0, Request{InputTokens: n, MaxTokens: 2})
	if err != nil {
		panic(err)
	}
	for at, ok := e.NextEvent(); ok; at, ok = e.NextEvent() {
		more, _ := e.Advance(at)
		evs = append(evs, more...)
	}
	for _, ev := range evs {
		if ev.ID == info.ID && ev.Kind == EvToken {
			return ev.At
		}
	}
	panic("no token")
}

// decodeCurve returns the steady-state gap between tokens of one stream when b streams run together.
func decodeCurve(p Params, b int) time.Duration {
	e := mustEngine(p, 128, 0)
	var first int64
	var times []time.Duration
	var all []Event
	for i := range b {
		info, evs, err := e.Submit(0, Request{InputTokens: 1, MaxTokens: curveSteps})
		if err != nil {
			panic(err)
		}
		if i == 0 {
			first = info.ID
		}
		all = append(all, evs...)
	}
	for at, ok := e.NextEvent(); ok; at, ok = e.NextEvent() {
		more, _ := e.Advance(at)
		all = append(all, more...)
	}
	for _, ev := range all {
		if ev.ID == first && ev.Kind == EvToken {
			times = append(times, ev.At)
		}
	}
	return times[curveSteps/2] - times[curveSteps/2-1]
}

// kvAdmitted is the most requests that hold a slot at once (the rest queue) when 64 identical requests
// arrive together at a worker with 64 slots.
func kvAdmitted(p Params, input int) int {
	e := mustEngine(p, 64, 64)
	for range 64 {
		if _, _, err := e.Submit(0, Request{InputTokens: input, MaxTokens: 500}); err != nil {
			break
		}
	}
	peak := e.Stats().Active
	for at, ok := e.NextEvent(); ok; at, ok = e.NextEvent() {
		if _, err := e.Advance(at); err != nil {
			panic(err)
		}
		peak = max(peak, e.Stats().Active)
	}
	return peak
}

func renderCurves() string {
	var b strings.Builder
	d, _ := Profile("default")
	fmt.Fprintf(&b, "Profile `default` (hash `%s`), noise off, one request on an idle worker.\n\n", d.Hash()[:12])
	b.WriteString("Prefill: time to the first token against prompt length.\n\n| Prompt tokens | `default` TTFT (ms) | `fast` (ms) | `slow` (ms) |\n| ---: | ---: | ---: | ---: |\n")
	for _, n := range []int{1, 128, 512, 1024, 2048, 4096, 8192} {
		fmt.Fprintf(&b, "| %d | %s | %s | %s |\n", n, fmtMs(prefillCurve(noiseFree("default"), n)), fmtMs(prefillCurve(noiseFree("fast"), n)), fmtMs(prefillCurve(noiseFree("slow"), n)))
	}
	b.WriteString("\nDecode: the gap between tokens of one stream, and the throughput, against the number of concurrent streams (`default`).\n\n")
	b.WriteString("| Concurrent streams | Step time (ms) | Per-stream tokens/s | Aggregate tokens/s |\n| ---: | ---: | ---: | ---: |\n")
	for _, n := range []int{1, 2, 4, 8, 16, 32, 64} {
		gap := decodeCurve(noiseFree("default"), n)
		per := 1 / gap.Seconds()
		fmt.Fprintf(&b, "| %d | %s | %.1f | %.0f |\n", n, fmtMs(gap), per, per*float64(n))
	}
	b.WriteString("\nKV budget: the most requests holding a slot at once (the rest wait in the queue) when 64 identical requests arrive together at a worker with 64 slots, each with `max_tokens` 500. A request is admitted when its prompt fits, so the peak is reached in the first admission wave; later KV growth can then force preemptions. 0 means the prompt can never fit and is refused.\n\n")
	b.WriteString("| Prompt tokens | `default` (32768 KV tokens) | `kv-tight` (6144) | `slow` (16384) |\n| ---: | ---: | ---: | ---: |\n")
	for _, n := range []int{128, 512, 2048, 4096, 8192} {
		fmt.Fprintf(&b, "| %d | %d | %d | %d |\n", n, kvAdmitted(noiseFree("default"), n), kvAdmitted(noiseFree("kv-tight"), n), kvAdmitted(noiseFree("slow"), n))
	}
	return b.String()
}

func TestDocsCurves(t *testing.T) {
	raw, err := os.ReadFile(docsPath)
	if err != nil {
		t.Fatal(err)
	}
	doc := string(raw)
	i, j := strings.Index(doc, beginMark), strings.Index(doc, endMark)
	if i < 0 || j < i {
		t.Fatalf("%s lacks the %s ... %s block", docsPath, beginMark, endMark)
	}
	want := beginMark + "\n" + renderCurves() + endMark
	if os.Getenv("UPDATE_SIM_DOCS") != "" {
		doc = doc[:i] + want + doc[j+len(endMark):]
		if err := os.WriteFile(docsPath, []byte(doc), 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	if got := doc[i : j+len(endMark)]; got != want {
		t.Errorf("the curve tables in %s are stale; run UPDATE_SIM_DOCS=1 go test ./internal/sim/engine -run TestDocsCurves\n--- want ---\n%s", docsPath, want)
	}
}

// The tables rest on closed forms; pin them so a change of the model cannot hide behind a regenerated doc.
func TestCurvesMatchClosedForms(t *testing.T) {
	p := noiseFree("default")
	for _, n := range []int{1, 1024, 8192} {
		want := ms(p.PrefillFixedMs + p.PrefillPerTokenMs*float64(n))
		if got := prefillCurve(p, n); got != want {
			t.Errorf("prefill(%d) = %v, want %v", n, got, want)
		}
	}
	for _, b := range []int{1, 8, 64} {
		want := ms(p.StepBaseMs + p.StepPerSeqMs*float64(b))
		if got := decodeCurve(p, b); got != want {
			t.Errorf("decode(b=%d) = %v, want %v", b, got, want)
		}
	}
	// Each request is admitted holding input+1 tokens, so 32768/(2048+1) = 15 fit.
	if got := kvAdmitted(p, 2048); got != 15 {
		t.Errorf("kvAdmitted(2048) = %d, want 15", got)
	}
}
